struct bio *bio_map_user_iovec(struct request_queue *q, const struct iov_iter *iter, gfp_t gfp_mask)
{
    struct bio *bio;
    struct page **pages;
    size_t nr_pages, i;
    ssize_t ret;

    ret = iov_iter_npages(iter, BIO_MAX_PAGES);
    if (ret < 0)
        return ERR_PTR(ret);
    nr_pages = ret;

    bio = bio_alloc(gfp_mask, nr_pages);
    if (!bio)
        return ERR_PTR(-ENOMEM);

    pages = kmalloc_array(nr_pages, sizeof(struct page *), gfp_mask);
    if (!pages) {
        bio_put(bio);
        return ERR_PTR(-ENOMEM);
    }

    ret = iov_iter_get_pages(iter, pages, iov_iter_count(iter), nr_pages, NULL);
    if (ret < 0) {
        kfree(pages);
        bio_put(bio);
        return ERR_PTR(ret);
    }

    for (i = 0; i < nr_pages; i++) {
        bio_add_page(bio, pages[i], PAGE_SIZE, 0);
    }

    kfree(pages);

    bio->bi_private = NULL;
    bio->bi_flags |= (1 << BIO_USER_MAPPED);

    return bio;
}

struct bio *bio_map_user_iovec(struct request_queue *q, const struct iov_iter *iter, gfp_t gfp_mask)
{
    struct bio *bio;
    unsigned long nr_pages;
    int i, ret;

    nr_pages = iov_iter_npages(iter, BIO_MAX_PAGES);
    if (!nr_pages)
        return ERR_PTR(-EINVAL);

    bio = bio_alloc(gfp_mask, nr_pages);
    if (!bio)
        return ERR_PTR(-ENOMEM);

    for (i = 0; i < nr_pages; i++) {
        struct page *page;
        unsigned long offset;
        size_t size;

        iov_iter_get_pages2(iter, &page, &offset, &size, 1);
        if (!page) {
            ret = -EFAULT;
            goto unmap_bio;
        }

        ret = bio_add_page(bio, page, size, offset);
        if (!ret) {
            ret = -EFAULT;
            goto unmap_bio;
        }
    }

    if (bio_sectors(bio) == 0) {
        ret = -EFAULT;
        goto unmap_bio;
    }

    bio->bi_flags |= BIO_USER_MAPPED;
    return bio;

unmap_bio:
    bio_unmap_user(bio);
    bio_put(bio);
    return ERR_PTR(ret);
}

struct bio *bio_map_user_iov(struct request_queue *q, const struct iov_iter *iter, gfp_t gfp_mask)
{
    struct bio *bio;
    struct iov_iter i;
    size_t nr_pages;
    int ret;

    iov_iter_init(&i, *iter);

    nr_pages = iov_iter_npages(&i, 0);
    if (!nr_pages)
        return ERR_PTR(-EINVAL);

    bio = bio_alloc(gfp_mask, nr_pages);
    if (!bio)
        return ERR_PTR(-ENOMEM);

    ret = bio_iov_iter_get_pages(bio, &i);
    if (ret < 0) {
        bio_put(bio);
        return ERR_PTR(ret);
    }

    if (i iov_iter_count() != 0) {
        bio_put(bio);
        return ERR_PTR(-EFAULT);
    }

    bio->bi_flags |= BIO_USER_MAPPED;
    return bio;
}
